    pts=set(pairs)
    res={}
    # vertical mirror about col w
    for w in range(W):
        for q in pts:
            if (q[0], 2*w-q[1]) not in pts and (q[0],q[1]) in pts: break
        else:
            if all((r,2*w-c) in pts for r,c in pts): res[f'v_mirror_c={w}']=True
    for h in range(H):
        if all((2*h-r,c) in pts for r,c in pts): res[f'h_mirror_r={h}']=True
    # point sym about (a,b): (r,c)->(2a-r,2b-c)
    for a in [0.5*x for x in range(H)]:
        for b in [0.5*x for x in range(W)]:
            if all((2*a-r,2*b-c) in pts for r,c in pts): res[f'point_sym_a={a}b={b}']=True
    # anti-diag (transpose-ish): (r,c)->(c',r'): need mapping c->? 
    # general 180 rotations of axes combos
    for dr,dc in itertools.product([1,-1],[1,-1]):
        for a in range(H):
