from collections import deque
def solve(g):
    h=len(g); w=len(g[0])
    seeds=[c for r in g for c in r if c!=0]
    seed=max(seeds,key=lambda c:sum(r.count(c) for r in g))
    out=[r[:] for r in g]
    q=deque()
    for i in range(h-1,-1,-1):
        for j in range(w-1,-1,-1):
            if out[i][j]==seed: q.append((i,j)); out[i][j]=3
    while q:
        i,j=q.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and out[ni][nj]==seed:
                out[ni][nj]=3; q.append((ni,nj))
    return out
